import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    try:
        sessions_path = os.path.join(d, '../../sessions')
    except:
        sessions_path = os.path.join(d, '..', '..\\sessions')
    t = open(sessions_path + '/' + os.path.basename(d) + '.jsonl').read()

    G = {}
    # Find demo pairs and test input
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, t):
        k, side, h, w = m[1], int(m[2]), int(m[3])
        rows_text = t[m.end():].split('\n')[:h]
        clean_rows = [r.strip().replace('\\', '').replace('\t', ' ').strip() for r in rows_text]
        valid_rows = [r for r in clean_rows if r and all(x.isdigit() for x in r.split())]

        if valid_rows and all(len(r) == w for r in valid_rows):
            grid = [[int(x) for x in r.split()] for r in valid_rows]
            if k not in G:
                G[k] = grid

    return G

