import os, glob, re, json

def load_grids_from_session():
    """Load all demo pairs and test input from session jsonl file"""
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        print("No RLM_SESSION_DIR environment variable set")
        return {}

    # Find the sessions folder relative to current directory
    try:
        base = os.path.dirname(d)
        session_file = os.path.join(base, '..', '..\\sessions\\' + os.path.basename(d) + '.jsonl')
        session_file = session_file.replace('\\', '/')  # Normalize

        # Alternative path structure
        if not os.path.exists(session_file):
            # Try different structure based on common patterns
            parent = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
            potential_paths = [
                os.path.join(parent, 'sessions/' + os.path.basename(d) + '.jsonl'),
                '/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference-4/play/users/u011/system/state/sessions/' + os.path.basename(d) + '.jsonl',
            ]
            for p in potential_paths:
                if os.path.exists(p):
                    session_file = p
                    break
    except Exception as e:
        print(f"Error finding session file: {e}")

    if not os.path.exists(session_file):
        print(f"Session file not found: {session_file}")
        return {}

    content = open(session_file).read()

    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, content):
        k, side, h, w = m[1], int(m[2]), int(m[3])

        # Get rows after this marker
        remaining = content[m.end():]
        lines = [line.strip() for line in remaining.split('\n')][:h]

        valid_rows = []
        for line in lines:
            line = line.replace('\\', '').replace('\t', ' ').strip()
            if line and all(x.isdigit() for x in line.split()):
                valid_rows.append(line)

        if valid_rows and all(len(r) == w for r in valid_rows):
            grid = [[int(x) for x in r.split()] for r in valid_rows]
            if k not in G:
                G[k] = grid

    return G

